const maxFileSize = 10 * 1024 * 1024 // 10 МБ

// Разрешённые расширения файлов, которые можно загружать.
var allowedExtensions = map[string]bool{
	".jpg":  true,
	".jpeg": true,
	".png":  true,
	".gif":  true,
	".pdf":  true,
	".txt":  true,
}

// UploadHandler — HTTP-обработчик для загрузки файлов.
// Принимает POST-запрос с multipart/form-data и сохраняет файл на диск.
// Проверяет:
//   - тип запроса (должен быть POST)
//   - наличие поля "file" в multipart-данных
//   - расширение файла (должно быть в списке разрешённых)
//   - размер файла (не должен превышать maxFileSize)
//
// При успешной загрузке возвращает 200 OK с сообщением о сохранении.
// При ошибке возвращает соответствующий код ошибки (400, 413, 500).
func UploadHandler(w http.ResponseWriter, r *http.Request) {
	// Проверяем метод запроса: принимаем только POST.
	if r.Method != http.MethodPost {
		http.Error(w, "Метод не поддерживается. Используйте POST.", http.StatusMethodNotAllowed)
		return
	}

	// Ограничиваем размер тела запроса, чтобы избежать переполнения памяти.
	// Это дополнительная защита на уровне HTTP-сервера.
	r.Body = http.MaxBytesReader(w, r.Body, maxFileSize)

	// Парсим multipart-форму. Если что-то пошло не так — возвращаем ошибку.
	err := r.ParseMultipartForm(maxFileSize)
	if err != nil {
		log.Printf("Ошибка парсинга multipart-формы: %v", err)
		http.Error(w, "Некорректные данные формы.", http.StatusBadRequest)
		return
	}

	// Получаем файл из поля "file".
	file, header, err := r.FormFile("file")
	if err != nil {
		log.Printf("Ошибка получения файла из формы: %v", err)
		http.Error(w, "Файл не найден или не был загружен.", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// Извлекаем имя файла из заголовка.
	filename := header.Filename
	if filename == "" {
		http.Error(w, "Имя файла не указано.", http.StatusBadRequest)
		return
	}

	// Проверяем расширение файла.
	ext := strings.ToLower(filepath.Ext(filename))
