import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantLock;

/**
 * Ограничитель частоты запросов (Rate Limiter) на основе алгоритма "Token Bucket" (корзина с токенами).
 *
 * <p>Алгоритм работает следующим образом:
 * <ul>
 *   <li>Есть корзина, которая может содержать максимум {@code maxTokens} токенов.</li>
 *   <li>Токены добавляются в корзину со скоростью {@code refillRate} токенов в секунду.</li>
 *   <li>Каждый запрос требует один токен. Если в корзине есть хотя бы один токен — запрос разрешается,
 *       и токен изымается. Иначе — запрос отклоняется.</li>
 * </ul>
 *
 * <p>Класс является потокобезопасным: все операции синхронизированы через {@link ReentrantLock}.
 */
public class TokenBucketRateLimiter {

    /**
     * Максимальное количество токенов, которое может находиться в корзине.
     * Это верхний предел накопленных токенов.
     */
    private final long maxTokens;

    /**
     * Скорость пополнения корзины: сколько токенов добавляется за одну секунду.
     * Например, если refillRate = 10, то каждые 100 мс добавляется 1 токен.
     */
    private final double refillRatePerSecond;

    /**
     * Текущее количество токенов в корзине.
     * Используется атомарный тип для точного отслеживания изменений во времени.
     * Значение может быть дробным, так как пополнение происходит непрерывно.
     */
    private double currentTokens;

    /**
     * Время последнего обновления количества токенов (в наносекундах).
     * Хранится как {@link AtomicLong} для атомарного чтения/записи.
     */
    private final AtomicLong lastRefillTimeNanos;

    /**
     * Блокировка для обеспечения потокобезопасности операций над состоянием корзины.
     * Используется реентерабельная блокировка, чтобы один поток мог многократно
     * вызывать методы класса без взаимной блокировки.
     */
    private final ReentrantLock lock;

    /**
     * Создаёт новый ограничитель частоты запросов.
     *
     * @param maxTokens         максимальное количество токенов в корзине (должно быть > 0)
