/**
 * Ищет активного пользователя по логину.
 *
 * @param login Логин пользователя для поиска (регистр не учитывается)
 * @return Опциональный объект с найденным активным пользователем, или пустой Optional, если пользователь не найден
 */
public Optional<User> findActive(String login) {
    // Получаем поток из коллекции всех пользователей
    return users.stream()
        // Фильтруем пользователей, у которых логин совпадает с переданным параметром (без учета регистра)
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // Оставляем только тех пользователей, которые не заблокированы и срок действия их учетной записи еще не истек
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))
        // Возвращаем первого подходящего пользователя в виде Optional
        .findFirst();
}
