/// <summary>
/// Выполняет асинхронное действие с повторными попытками при возникновении сетевых ошибок.
/// </summary>
/// <param name="action">Асинхронная функция, возвращающая целое число.</param>
/// <param name="attempts">Максимальное количество попыток выполнения действия.</param>
/// <returns>Результат успешного выполнения действия.</returns>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл для выполнения не более 'attempts' попыток
    for (var i = 0; i < attempts; i++)
    {
        try 
        {
            // Пытаемся выполнить переданное асинхронное действие и вернуть его результат
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Если произошла сетевая ошибка (HttpRequestException) и это не последняя попытка:

            // Вычисляем задержку с экспоненциальным бэкоффом:
            // 200 мс * 2^i (например: 200мс, 400мс, 800мс, ...)
            var delayMs = 200 * Math.Pow(2, i);

            // Ждем указанный интервал времени перед следующей попыткой
            await Task.Delay(TimeSpan.FromMilliseconds(delayMs));
        }
    }

