// Функция worker представляет собой функцию-работник (goroutine), которая обрабатывает задачи из канала jobs.
// Она читает задачи из входного канала, выполняет их и отправляет результаты в выходной канал.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // defer wg.Done() гарантирует, что после завершения работы воркера будет вызван метод Done на WaitGroup.
    // Это необходимо для корректного подсчета завершившихся горутины и ожидания всех работников перед закрытием программы.
    defer wg.Done()

    // Цикл for range jobs читает задачи из канала jobs до тех пор, пока канал не будет закрыт.
    // Каждый элемент j — это задача типа Job.
    for j := range jobs {
        // Вызываем функцию process для обработки текущей задачи j.
        // Возвращаются результат r и возможная ошибка err.
        r, err := process(j)

        // Если при обработке возникла ошибка:
        if err != nil {
            // Логируем ошибку с указанием ID задачи и текстом ошибки.
            log.Printf("job %d: %v", j.ID, err)
            // Пропускаем эту задачу и переходим к следующей (continue).
            continue
        }

        // Если обработка прошла успешно, отправляем результат r в канал results.
        // Оператор <- блокирует выполнение, пока место в канале не освободится (если канал буферизован) или пока потребитель не заберет значение.
        results <- r
    }
}
