```typescript
/**
 * Функция debounce (дебаунс) — откладывает выполнение переданной функции
 * до тех пор, пока не прекратятся вызовы в течение заданного времени.
 * 
 * @param fn - функция, которую нужно дебаунсить
 * @param ms - задержка в миллисекундах
 * @returns обёрнутая функция с тем же набором аргументов
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Она нужна, чтобы можно было отменить предыдущий таймер при новом вызове.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и исходная.
  return (...args: Parameters<T>) => {
    // Если уже есть активный таймер (t не undefined), отменяем его.
    // Это обеспечивает "перезапуск" таймера при каждом новом вызове.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер на указанный интервал (ms).
    // По истечении времени будет выполнена исходная функция fn с переданными аргументами.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

