import java.time.format.DateTimeFormatter
import java.time.Month

// Функция для парсинга даты из строки в заданном формате
fun parse(dateString: String): LocalDate {
    // Явно указываем формат: день (dd) / месяц (MM) / год (yyyy)
    // Это гарантирует, что "01/02/2024" будет распознано как 1 февраля 2024
    val formatter = DateTimeFormatter.ofPattern("dd/MM/yyyy")

    // Парсим строку в объект LocalDate
    return LocalDate.parse(dateString, formatter)
}

@Test
fun `parses date`() {
